/** Events */
export const events = {
	downloadProgress: makeEvent<DownloadProgress>("download-progress"),
	installProgress: makeEvent<InstallProgress>("install-progress"),
	modInstallFailed: makeEvent<ModInstallFailed>("mod-install-failed"),
	modInstallProgress: makeEvent<ModInstallProgress>("mod-install-progress"),
	modInstalled: makeEvent<ModInstalled>("mod-installed"),
	modToggle: makeEvent<ModToggle>("mod-toggle"),
	modUninstalled: makeEvent<ModUninstalled>("mod-uninstalled"),
	processExited: makeEvent<ProcessExited>("process-exited"),
	processSpawned: makeEvent<ProcessSpawned>("process-spawned"),
};

/* Types */
export type Account = {
	/**
	 *  Local UUID v4 — disambiguates entries; key suffix for any per-account
	 *  secret storage (currently unused; reserved for the deferred MS auth).
	 */
	id: string,
	/**  Display name (MC username). */
	name: string,
	/**  MC UUID, canonical hyphenated form. */
	uuid: string,
	/**  Unix seconds. `None` for offline (never expires). */
	expires_at: number | null,
};

export type AppFile = AppFile_Serialize | AppFile_Deserialize;

export type AppFile_Deserialize = {
	version: number,
	active_instance?: string | null,
	onboarding?: OnboardingState_Deserialize,
};

export type AppFile_Serialize = {
	version: number,
	active_instance?: string | null,
	onboarding: OnboardingState_Serialize,
};

export type AuditEntry = {
	/**
	 *  Milliseconds since Unix epoch, as `f64` so JavaScript's `number`
	 *  type can round-trip it without precision loss (`Date.now()`
	 *  returns f64-compatible values too). UI formats with `new Date(ts)`.
	 */
	ts: number | null,
	method: string,
	url: string,
	/**  Module that initiated the call (`"versions"`, `"jre"`, etc.). */
	initiator: string,
	/**
	 *  Bytes transferred. `None` if the call is in progress or failed
	 *  before any body was read.
	 */
	bytes: number | null,
	/**
	 *  HTTP status code if the response was received, else `None`
	 *  (network error before status).
	 */
	status: number | null,
};

/**
 *  Compatibility verdict for a local mod jar against a target instance.
 *  Crosses the IPC boundary. A jar is "compatible" iff neither flag is set.
 */
export type CompatVerdict = {
	/**
	 *  Display loader name detected in the jar ("Fabric" / "Forge" / …),
	 *  or `None` when the jar has no recognised descriptor.
	 */
	detected_loader: string | null,
	/**  `major.minor` Minecraft version detected in the jar, or `None`. */
	detected_mc: string | null,
	/**  The mod's display name from the jar, or `None`. */
	detected_name: string | null,
	/**  The jar's loader family is the opposite of the instance's. */
	loader_mismatch: boolean,
	/**  The jar's declared MC `major.minor` differs from the instance's. */
	mc_mismatch: boolean,
};

export type CrashReport = {
	path: string,
	/**
	 *  First ~500 chars of the crash report — enough to show the
	 *  stack-trace head in a banner without loading the full file.
	 */
	preview: string,
};

